SELECT DISTINCT SWS.ID, SWS.BADGE, SWS.CHECK_DATE, SS. NAME, SS.COMP_NAME, SS.DEP_NAME, SWS.SIGN_DATE, SWS.OBJECTION, SWS.IS_OBJECTION, SWS.CREATE_TIME, SWS.SIGN_STATUS FROM SMT_ATTENDANCE_SIGN SWS LEFT JOIN SMT_STAFF SS ON SWS.BADGE = SS.BADGE LEFT JOIN SMT_PARK_BU SPB ON SS.COMP_ID = SPB.COMP_ID
AND SWS.BADGE = #{query.badge}
AND SPB.PARK_ID = #{query.parkId}
AND SPB.PARK_ID IN
#{tempId}
AND SS. NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND SWS.CHECK_DATE = #{query.checkDate}
AND SS.COMP_ID = #{query.compId}
AND SS.DEP_ID = #{query.depId}
AND SWS.SIGN_STATUS = #{query.signStatus}
ORDER BY SWS.CREATE_TIME DESC

