update SMT_ATTENDANCE_SIGN set SIGN_STATUS = 3 WHERE id in ( SELECT DISTINCT SWS.ID FROM SMT_ATTENDANCE_SIGN SWS LEFT JOIN SMT_STAFF SS ON SWS.BADGE = SS.BADGE LEFT JOIN SMT_PARK_BU SPB ON SS.COMP_ID = SPB.COMP_ID
AND SPB.PARK_ID = #{query.parkId}
AND SWS.CHECK_DATE = #{query.checkDate}
AND SWS.SIGN_STATUS = #{query.signStatus}
)

